pub fn grow (&mut self, n: usize, value: bool) {
    let new_len = self.nbits.checked_add(n).expect("new length overflows");
    self.storage.resize((new_len + 31) / 32, 0);
    for i in self.nbits..new_len {
        let block_index = i / 32;
        let bit_index = i % 32;
        if value {
            self.storage[block_index] |= 1 << (31 - bit_index);
        }
    }
    self.nbits = new_len;
}

